import {ThemeProvider} from '@primer/react-brand'
import {t} from '@github-ui/swp-core/lib/utils/localization'

import {LinkColumn} from './components/LinkColumn/LinkColumn'
import {Newsletter} from './components/Newsletter/Newsletter'
import {StaffToggleBar} from './components/StaffToggleBar/StaffToggleBar'
import {SubFooter} from './components/SubFooter/SubFooter'

import {
  ARIA_HEADING,
  LEGAL_NAV_LABEL,
  SELECT_LANGUAGE_LABEL,
  SOCIAL_NAV_LABEL,
  cookieConsentItems,
  defaultLocaleOptions,
  newsletter,
  sections,
  socialLinks,
  subFooterLegalLinks,
} from './MarketingFooter.data'
import type {LocaleConfig, LocaleOption, MarketingFooterProps, RailsLocaleOption} from './marketing-footer.types'

import styles from './MarketingFooter.module.css'

function toLocaleOption(entry: RailsLocaleOption): LocaleOption {
  return {
    label: t(entry.displayName),
    locale: entry.selectorLocale,
    analyticsLabel: entry.analyticsLabel,
  }
}

function buildLocaleConfig(railsOptions: RailsLocaleOption[] | undefined, currentLocale: string): LocaleConfig {
  const options = railsOptions && railsOptions.length > 0 ? railsOptions.map(toLocaleOption) : defaultLocaleOptions()
  const current = options.find(o => o.locale.startsWith(currentLocale.slice(0, 2))) ?? options[0]
  const currentLabel = current ? current.label : t('English')

  return {
    triggerAriaLabel: `${currentLabel} - ${SELECT_LANGUAGE_LABEL()}`,
    options,
    currentLocale: current ? current.locale : 'en-us',
  }
}

export function MarketingFooter(props: MarketingFooterProps) {
  const {
    cookieConsentEnabled = false,
    colorMode = 'auto',
    currentLocale = 'en-us',
    localeOptions,
    showAdminToggle = false,
    isAdminModeOn = false,
    adminTogglePath,
    showUiOptOut = false,
    isUiOptedOut = false,
    uiOptOutTogglePath,
  } = props

  const localeConfig = buildLocaleConfig(localeOptions, currentLocale)
  const currentYear = new Date().getFullYear()
  const subFooter = {
    copyrightLabel: `\u00a9 ${currentYear} GitHub, Inc.`,
    copyrightYear: currentYear,
    legalLinks: subFooterLegalLinks(),
    cookieConsentItems: cookieConsentItems(),
  }

  return (
    <ThemeProvider colorMode={colorMode}>
      <footer className={styles.footer} role="contentinfo" data-analytics-category="Footer">
        <h2 className={styles.srOnly}>{ARIA_HEADING()}</h2>

        <div className={styles.container}>
          <div className={styles.topRow}>
            <Newsletter {...newsletter()} className={styles.newsletter} />

            <div className={styles.columns}>
              {sections().map(section => (
                <LinkColumn key={section.id} section={section} />
              ))}
            </div>
          </div>
        </div>

        <SubFooter
          subFooter={subFooter}
          legalNavLabel={LEGAL_NAV_LABEL()}
          socialNavLabel={SOCIAL_NAV_LABEL()}
          localeOverlayLabel={SELECT_LANGUAGE_LABEL()}
          socialLinks={socialLinks()}
          locale={localeConfig}
          cookieConsentEnabled={cookieConsentEnabled}
        />

        <StaffToggleBar
          showAdminToggle={showAdminToggle}
          isAdminModeOn={isAdminModeOn}
          adminTogglePath={adminTogglePath}
          showUiOptOut={showUiOptOut}
          isUiOptedOut={isUiOptedOut}
          uiOptOutTogglePath={uiOptOutTogglePath}
        />
      </footer>
    </ThemeProvider>
  )
}
